insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('producedwater', 'beginner', 'module', 'm01-what-this-engine-answers', 1, 'This engine answers a single question and dresses it several ways. Which question is it?', '["Given a required outlet concentration, which arrangement of devices reaches it for the least money spent.", "Given a measured inlet and outlet concentration, what efficiency to credit each device standing between them.", "Given this water, this oil and this equipment, what fraction of the dispersed oil comes out, and what is left in the water afterwards.", "Given this water and this oil, how much of the inlet oil is dissolved and how much of it is dispersed."]'::jsonb, 2, 'Every table in this course is that one question with a single input moved. The module carries no cost of any kind, it fits nothing back out of measured concentrations, and it has no dissolved oil model, so the split at the inlet is not a question it can be asked.'),
  ('producedwater', 'beginner', 'module', 'm01-what-this-engine-answers', 2, 'Why will this module not size anything from a concentration alone?', '["A concentration says how much oil is there and the distribution says how hard that oil is to remove, and every device here is characterised by the droplet size it removes half of.", "A concentration cannot be turned into an oil mass flow without the droplet population standing beside it, so this module wants both figures before it will close any balance at all over a stage.", "The median and the spread are what set the bin count and the span, so without them there is no grid to integrate over.", "A concentration is measured in a bottle and a distribution in the line, so the module keeps the treating figure."]'::jsonb, 0, 'The bin count and the span are declared defaults and arrive with the grid rather than with the water. The doctrine is about what a number can say: one water at one concentration can be easy or hard to treat, and only the droplet sizes say which.'),
  ('producedwater', 'beginner', 'module', 'm01-what-this-engine-answers', 3, 'What does the cut size d50c of a device mean in this module?', '["The smallest droplet the device removes at all, below which its grade efficiency falls to zero and the oil passes untouched.", "The median droplet size of the water leaving the device, which is the figure the next stage in a train inherits as its inlet.", "The droplet size at which a vendor measured that device''s published curve, carried across to this water.", "The droplet size the device removes half of, computed from that equipment''s own geometry and the fluid properties."]'::jsonb, 3, 'Half removed and half surviving is the definition, which is why the grade efficiency at the cut size is exactly one half. A device still removes a little below its cut size and a great deal above it, and the outlet median is a separate reported figure.'),
  ('producedwater', 'beginner', 'module', 'm01-what-this-engine-answers', 4, 'What is the whole difference between this engine and a table of fixed removal efficiencies?', '["The engine interpolates between the published efficiencies rather than rounding to the nearest entry, so a removal moves smoothly as the droplets change.", "Every cut size is computed from the equipment and the fluids, so the same device on finer water performs worse, which is what actually happens.", "The engine holds a separate efficiency table for each family of device and picks the entry matching the water it was given, so the lookup is done for the reader.", "The engine averages the published efficiencies of the devices in a train, so a stage that removes little pulls the overall figure down with it."]'::jsonb, 1, 'Nothing in this module is a fixed removal efficiency, interpolated or otherwise. A cut size falls out of geometry and fluid properties, and the removal follows from that cut size against the droplets actually present.'),
  ('producedwater', 'beginner', 'module', 'm01-what-this-engine-answers', 5, 'Which of these does this module actually compute?', '["The oil carried away in a hydrocyclone reject stream, balanced against the oil left in the treated water leaving the bank.", "The rate at which a media bed fouls over a run, and the backwash cycle that has to be scheduled to clear it.", "The droplet distribution leaving each stage, which the stage after it takes as its inlet.", "The droplets a chemical demulsifier coalesces upstream, which is how the water reaching the first device is made easier to treat."]'::jsonb, 2, 'No reject stream or oil recovery balance, no fouling over time, no backwash cycle and no chemical demulsifier or coalescer media is in this module. The outlet distribution carried forward is the coupling a train is built on.'),
  ('producedwater', 'beginner', 'module', 'm01-what-this-engine-answers', 6, 'This module exports 20 names. How do they divide?', '["13 are callable devices and 7 are frozen objects, strings or helpers, and all 13 carry the error contract.", "16 are callable and 4 are frozen objects or strings, and of the callable ones 13 carry the error contract while 3 are leaves.", "16 are callable and 4 frozen, and all 16 carry the error contract, since a leaf reports through its caller.", "All 20 are callable and none frozen, because the constants are reached through a call returning a copy."]'::jsonb, 1, 'A leaf answers with a bare number and has nowhere to put an error key, which is why 3 of the 16 callable names sit outside the error contract rather than inside it.'),
  ('producedwater', 'beginner', 'module', 'm01-what-this-engine-answers', 7, 'One of the three leaves is handed a state it has no answer for. What comes back, and what happens to it?', '["A zero, which the caller reads as a device that removed nothing and reports as a stage that ran and did no useful work.", "A thrown error, which the caller catches and raises again carrying the name of the input that caused the trouble.", "An object with a named error key, exactly as every other export in the module answers, because one contract covers all of them.", "A bare NaN, which is how a leaf says it has no answer, and the caller that wrapped it turns that silence into a named refusal."]'::jsonb, 3, 'This module throws nothing at all. A leaf is a helper with nowhere to put an error key, so it returns a bare NaN rather than a number that could pass for an answer, and that is a documented contract rather than an oversight.'),
  ('producedwater', 'beginner', 'module', 'm01-what-this-engine-answers', 8, 'The fraction of a plate pack projected area credited as settling area is 0.7. Which of the four kinds of number is that?', '["Declared: chosen or customary, with no publication in this repository to check it against.", "Derived: it follows from the projected area of one plate and the angle the pack is set at, so there is nothing left to check.", "Calibrated: it was chosen so that a pack at the module''s own default conditions lands where plate interceptors are customarily credited.", "Held for literature: the module states the absence and asks a caller to supply it."]'::jsonb, 0, 'It sits in the frozen declared object with the rest of the chosen numbers, and it is worth a large part of the plate pack answer. There is exactly one calibration in this module and it is not this.'),
  ('producedwater', 'beginner', 'module', 'm01-what-this-engine-answers', 9, 'A device cuts at ten micron. What is its grade efficiency at ten micron, and why is there nothing to validate in that?', '["One half at the declared sharpness of 3 and somewhat less at the derived sharpness of 2, because a sharper curve carries more of its removal near the cut size itself.", "It depends on the droplet distribution the device works on, since the curve is integrated against the bins first.", "Exactly one half, 0.500000000000, because that is what a cut size means, and it holds at every sharpness this module uses.", "Close to one half, with the departure set by where the bin holding the cut size falls."]'::jsonb, 2, 'The reduced-efficiency form is r over one plus r, so every curve in this module passes through one half at a ratio of one. A derived number follows from something else on the page and leaves nothing to argue about.'),
  ('producedwater', 'beginner', 'module', 'm01-what-this-engine-answers', 10, 'Standard gravity comes back out of this engine at 9.806650 m/s2 when the arithmetic is run on a rise velocity the engine reported. What does that establish?', '["That the rise velocity has been checked against a published measurement, since a constant can only be recovered from an answer that is already known to be right.", "That the arithmetic which produced the answer used that figure, which is a different claim from somebody having typed it into the source.", "That gravity is one of the declared constants of this module, exported in the same frozen object as every other chosen value in it.", "That the closed form and the full drag balance agree with each other, because only the two of them together can leave a clean constant behind."]'::jsonb, 1, 'Reading a constant out of source code proves that somebody typed it. Recovering it from a return value proves the answer was built with it, and only the second claim survives a rewrite of the implementation.'),
  ('producedwater', 'beginner', 'module', 'm01-what-this-engine-answers', 11, 'Which figure in this module has no derivation behind it at all, and what does the module say about it?', '["The short-circuit allowance of 1.5, chosen so that a basin of customary proportions reproduces the cut size API 421 credits such a basin with.", "The sharpness of 3, fitted so that the gravity devices reproduce the removals published for them, and fixed in the module rather than open to a caller.", "The reference loading of 10 m per hour, which was fitted to the bed data this repository carries and is the one number in the module with a measurement behind it.", "The attachment efficiency of 0.01, chosen so a cell at the module''s own defaults lands where flotation is customarily credited, and it is an input a caller can move."]'::jsonb, 3, 'The allowance of 1.5 and the sharpness of 3 are declared, which is a different status: customary or chosen, with nothing here to check them against. No bed data of any kind is in this repository.'),
  ('producedwater', 'beginner', 'module', 'm01-what-this-engine-answers', 12, 'What does this module do about the value of the dissolved and soluble oil floor?', '["It states on every train return that a floor exists, reports no value for it, and applies one only where a caller supplies it.", "It carries a default floor among its declared constants and warns whenever a train reports an outlet concentration below that figure.", "It removes dissolved oil in the last stage of any train that has one and reports the remainder separately from the dispersed oil.", "It refuses to report an outlet concentration at all until a caller supplies the floor, on the grounds that an outlet below it would be meaningless."]'::jsonb, 0, 'No device here removes dissolved oil, so a floor under every outlet is real and its value is the caller''s. Held for literature means the module states the absence rather than guessing, and the train answers in full without one.'),
  ('producedwater', 'beginner', 'module', 'm01-what-this-engine-answers', 13, 'The jest suite pins the declared constants of this module by literal. What does a pin buy, and what does it not?', '["It traces each constant to the publication the module cites for it, so a reviewer can follow any chosen number of them back to its own source.", "It fixes the value for callers, so a pinned constant can no longer be moved by an input.", "It makes moving one a reviewed act instead of a silent one, and it says nothing whatever about whether the value is right.", "It proves the constant reaches every line that needs it, since a second copy fails the pin."]'::jsonb, 2, 'The pin is an exact key-set match, so adding or removing a constant fails until the pin is updated. Both the module and its test say in as many words that pinning is all a gate can do here.'),
  ('producedwater', 'beginner', 'module', 'm01-what-this-engine-answers', 14, 'A studio screen shows a train that ran, every concentration printed, and a verdict field holding null. Which of the three acts is that?', '["A refusal, since a null is what this module hands back whenever it has no answer for the state it was given.", "A withheld verdict: the computation ran in full and the pass or fail was declined, with a reason given for declining it.", "A warning, because the figures all arrived and the module has attached a note to them.", "A failure, since a train whose result cannot be judged against a specification has not produced anything a designer can use."]'::jsonb, 1, 'A refusal comes back as an object carrying a named error and nothing that could pass for an answer, and a warning withholds nothing at all. Here the concentrations are real and only the judgement is missing.'),
  ('producedwater', 'beginner', 'module', 'm01-what-this-engine-answers', 15, 'Every number in this module that is a choice rather than a derivation sits in one frozen object of 55 keys. What is the argument for that?', '["A frozen object can be checked as a whole against the golden file, which is impossible for a value written into the middle of a formula.", "Reading each value at the time of the call is what lets a caller override any of them, which a literal written into a line would not allow.", "It keeps the derived numbers apart from the declared ones, so that the derivations can be printed in one table and checked together.", "A chosen number written into the line that consumes it is a number nobody will find again, so one place is what makes moving any of them visible."]'::jsonb, 3, 'The engine reads each one from that object rather than inlining it, and the object is what a reviewer opens. Whether a caller can override a particular value is a separate question from where the default is kept.'),
  ('producedwater', 'beginner', 'module', 'm02-the-water-and-the-oil', 1, 'In the viscosity sweep over six temperatures at 62000 ppm TDS, the salinity factor column reads 1.111600 on every row. Why?', '["The factor is a declared constant of the module rather than something computed, so no input of any kind can move it.", "The factor depends on the dissolved solids alone, and only the temperature moved down that sweep.", "The factor is quoted against the value in the last row of the table, so the row it is normalised on necessarily reads one.", "The temperature effect is already inside the fresh water column, so the factor is what is left once that effect has been divided out of the brine figure."]'::jsonb, 1, 'The salinity factor is one plus 1.8 times the mass fraction of dissolved solids. The multiplier is declared and the factor is not: hold the salinity at 62000 ppm and it repeats, and the sweep at 41 C over six salinities moves it from 1.000000 to 1.504000.'),
  ('producedwater', 'beginner', 'module', 'm02-the-water-and-the-oil', 2, 'Across the sweep from 20 C to 95 C at one salinity, the brine viscosity falls by a factor of 3.403251. What does a designer take from that?', '["Viscosity is a weak enough function of temperature over any real produced water range that a summer sample and a winter sample can be treated as the same duty.", "The cut size of a gravity device moves by that same factor of 3.403251, since the cut size and the rise velocity are the same quantity read two ways.", "The figure is the ratio of the fresh water column to the brine column, so it measures what the salinity is worth rather than what the temperature is worth.", "The same vessel is catching a very different droplet out of the same water at the two ends of that sweep, because a rise velocity goes as one over the viscosity."]'::jsonb, 3, 'A rise velocity carries one over the viscosity, so the droplets in the hotter water rise faster and the device catches finer oil. A cut size carries the square root of that group rather than the whole of it, and the ratio column is each brine viscosity over the last row of its own column.'),
  ('producedwater', 'beginner', 'module', 'm02-the-water-and-the-oil', 3, 'Water at 41 C is heated upstream of a basin and nothing else about the stream changes. Which way does the basin cut size move, and why?', '["Finer, because the water thins, every droplet rises faster, and a device that catches a droplet rising at the design velocity now catches a smaller one.", "Coarser, because the crude thins with temperature as well and the density difference falls away faster than the viscosity does.", "It does not move, because the cut size comes from the flow over the plan area and neither of those is a property of the water.", "Finer, because the brine density rises with temperature and a heavier brine carries a larger density difference against the oil."]'::jsonb, 0, 'The surface loading is unchanged by heating and the cut size is the inversion of the rise balance at that loading, which does carry the viscosity. Brine density falls with temperature rather than rising, and the module states the fit it uses over its own temperature range.'),
  ('producedwater', 'beginner', 'module', 'm02-the-water-and-the-oil', 4, 'What form does the salinity correction on viscosity take in this module, and what status does it have?', '["A power law in the mass fraction whose exponent was fitted to the published brine data this repository carries for the purpose.", "A multiplier read from the same three-constant temperature fit, so that salinity and temperature enter the answer through one expression.", "One plus 1.8 times the mass fraction of dissolved solids, with the multiplier declared and no publication here to check it against.", "One plus the mass fraction multiplied by the brine density slope of 700, which is the one constant covering both of the salinity effects."]'::jsonb, 2, 'The correction is linear in the mass fraction and the multiplier sits in the frozen declared object. The slope of 700 is the other salinity effect entirely, which is what dissolved solids do to the density.'),
  ('producedwater', 'beginner', 'module', 'm02-the-water-and-the-oil', 5, 'A caller hands this module a salinity just above 300000 ppm TDS. What comes back, and what is the stated reason?', '["The answer computed at 300000 ppm, with a warning saying the input was moved up to the top of the stated range, on the grounds that the correction is very nearly flat by the time it gets there.", "A refusal naming the figure, because the salinity correction here is stated to 300000 ppm and past saturation a linear correction has nothing behind it.", "A refusal naming the figure, because no brine of that salinity exists at any temperature this module''s density fit is stated over.", "The answer with a warning, because the module holds the salinity band as customary rather than as a limit on the correction itself."]'::jsonb, 1, 'The refusal names the input and the limit together. Moving a bad input quietly to the nearest good one would delete the input, and the caller would never learn which number the answer belonged to.'),
  ('producedwater', 'beginner', 'module', 'm02-the-water-and-the-oil', 6, 'A negative total dissolved solids figure reaches this module. What is the shape of what happens, and why does it matter beyond the obvious?', '["It is refused with the quantity stated first and then the input named, which is the shape every input check in this engine takes.", "It is treated as fresh water, since a salinity below zero and a salinity of zero produce the same correction factor of 1.000000.", "It is answered with a warning, because the linear correction remains computable below zero and the caller may be probing the sensitivity.", "It is refused without naming the figure, because a quantity that cannot be negative needs no explanation beyond its own definition."]'::jsonb, 0, 'The engine names the quantity, names the range and names the figure that fell outside it. Quietly moving a bad value to the nearest usable one would hide which number the answer belonged to.'),
  ('producedwater', 'beginner', 'module', 'm02-the-water-and-the-oil', 7, 'Two rows of the brine density table sit at 41 C, one at 0 ppm TDS and one at 62000. The fresh column reads 991.861174 on both. What follows?', '["The fresh column is a declared reference rather than a computed figure, which is why it repeats whenever the salinity is the only input that moved.", "The salinity term is applied to the fresh figure as a multiplier rather than as an addition, so that the 62000 ppm row is simply the 0 ppm row above it scaled by the salinity factor of 1.111600.", "The brine density has no temperature dependence at all once the salinity term is added, which is why the fit is stated over so narrow a range.", "The whole of the difference between 991.861174 and 1035.261174 is the dissolved solids, because the temperature term produced the same number twice."]'::jsonb, 3, 'Temperature sets the fresh water density and salinity adds to it. The factor of 1.111600 is the viscosity correction, and it is a multiplier on a different property entirely.'),
  ('producedwater', 'beginner', 'module', 'm02-the-water-and-the-oil', 8, 'What does the declared constant brineDensitySlopeKgM3 of 700 set, and what is its status?', '["The density of the dissolved solids themselves, out of which this module assembles a brine density by treating the water as a mixture of salt and water.", "The upper density this module will describe a brine at, past which the salinity correction is refused rather than extrapolated.", "How fast the brine density rises with dissolved solids, chosen rather than published, and kept in the same frozen object as the rest.", "The rate at which the brine density falls with temperature, which is the other half of the two term fit the module uses."]'::jsonb, 2, 'It is the salinity slope on density and nothing else. The module states the temperature range its fresh water density fit holds over, and that range is where a refusal on temperature comes from.'),
  ('producedwater', 'beginner', 'module', 'm02-the-water-and-the-oil', 9, 'How does this module get from a degree API to a crude density at treating temperature?', '["The API figure becomes a specific gravity at 60 F and is taken against the brine density of the stream, so the difference the devices need falls out in one step.", "The API figure becomes a specific gravity at 60 F, that is taken against a declared reference water of 999 kg/m3, and the result is thinned at a declared 0.0007 for each degree.", "The API figure is converted directly to a density at treating temperature by the standard relation, which carries its own temperature term.", "The API figure becomes a specific gravity, and the thermal expansion is looked up for the crude family the gravity places it in."]'::jsonb, 1, 'Three steps, two of them declared choices. The reference water is a choice, and the one expansion rate is applied to every crude in the sweep from the heaviest to the lightest, which real crudes do not do.'),
  ('producedwater', 'beginner', 'module', 'm02-the-water-and-the-oil', 10, 'The UZERE crude is 24 API and the stream is at 41 C. What does the module make of it?', '["A specific gravity of 0.909968 and a density of 892.869375 kg/m3 at treating temperature.", "A specific gravity of 0.909968 with the density read against a reference water of 1000 kg/m3 rather than the declared figure.", "A specific gravity of 0.909968 and a density of 967.534410 kg/m3.", "A density of 892.869375 kg/m3 at 60 F, which the module then corrects to treating temperature before any device is sized."]'::jsonb, 0, 'The specific gravity is taken at 60 F and the density is reported at the line temperature. 967.534410 is the 12 API row of the same sweep, and reading a crude at its reference temperature rather than at the line temperature is the ordinary way this chain goes wrong.'),
  ('producedwater', 'beginner', 'module', 'm02-the-water-and-the-oil', 11, 'The UZERE brine is 1035.261174 kg/m3 and its crude is 892.869375. What is the density difference doing in this module?', '["It is 142.391799 kg/m3, and it is what the grade efficiency curve is integrated against.", "It is the sum of those two densities, because buoyancy on a droplet carries the weight of both fluids at once.", "It is 142.391799 kg/m3 at 60 F, corrected to the line temperature later.", "It is 142.391799 kg/m3, and it is the entire driving force behind every gravity and centrifugal device here."]'::jsonb, 3, 'Buoyancy is the difference, both densities are already reported at the line temperature, and the grade efficiency is integrated against the droplet bins rather than against any density.'),
  ('producedwater', 'beginner', 'module', 'm02-the-water-and-the-oil', 12, 'Across the six crudes of the API sweep the density difference against the UZERE brine runs from 67.726764 to 253.057299 kg/m3. What is that worth?', '["A factor of 3.736445 in the driving force, and the same factor again on every cut size, since the two are proportional.", "A factor of 3.736445 in the driving force, which the short-circuit allowance of 1.5 was chosen to absorb on an ordinary basin.", "A factor of 3.736445 in the driving force, and the same factor lands on every cut size squared.", "A factor of 3.736445 in the driving force, and no effect on a cut size at all, which follows from the flow over the plan area."]'::jsonb, 2, 'The cut size carries the square root of that group, so the factor lands on the cut size squared. It is a property of the two fluids, settled before anybody opens an equipment catalogue.'),
  ('producedwater', 'beginner', 'module', 'm02-the-water-and-the-oil', 13, 'A caller describes an oil heavier than the water it sits in. What does this module do?', '["It reports a negative rise velocity and a cut size with a warning attached, since the algebra remains computable throughout.", "It refuses by name, saying the oil must be lighter than the water for it to rise.", "It reports the settling velocity of the oil instead and marks the device as a bottom draw rather than an overflow.", "It answers with a cut size of NaN and no error, leaving the caller to notice that nothing usable came back."]'::jsonb, 1, 'A method built on buoyancy has nothing to say about that case, so the module declines rather than returning a cut size somebody might use. It is physically possible for very heavy crude in fresh hot water.'),
  ('producedwater', 'beginner', 'module', 'm02-the-water-and-the-oil', 14, 'At 41 C the brine viscosity runs from 0.000639217342 Pa.s at 0 ppm TDS to 0.000961382883 at 280000. Taken on its own, what does that column do to a cut size, and what else moves with it?', '["On its own a thicker water slows every droplet and coarsens the cut, and salinity raises the brine density at the same time, which moves the driving force the other way.", "On its own a thicker water slows every droplet and coarsens the cut, and nothing else in the fluid properties responds to salinity at all.", "On its own a thicker water speeds every droplet up, because the drag term sits underneath the density difference in the balance.", "Nothing at all, since the viscosity enters the removal rather than the cut size and the removal is a fraction of the oil."]'::jsonb, 0, 'Salinity acts on both of the properties this course runs on. Reading one column of a sweep and calling the duty harder or easier leaves out the other one, and both belong to the same water.'),
  ('producedwater', 'beginner', 'module', 'm02-the-water-and-the-oil', 15, 'Which two steps between a degree API and a crude density at treating temperature rest on a declared choice?', '["The relation from degrees API to specific gravity, and the reference water of 999 kg/m3 the gravity is taken against.", "The reference temperature of 60 F, and the API range the module holds to.", "The reference water the specific gravity is taken against, and the rate at which the crude thins with temperature.", "The thermal expansion rate of 0.0007 for each degree, and the brine density slope the difference is then taken against."]'::jsonb, 2, 'The API relation itself is standard and the reference temperature comes with it. The brine slope belongs to the water rather than to the crude, and the API range is a stated limit rather than a step in the chain.'),
  ('producedwater', 'beginner', 'module', 'm03-the-droplets', 1, 'How does this module describe the oil carried in the water?', '["As a log-normal distribution in droplet volume, given by a median diameter d50 and a log standard deviation sigma, discretised into volume bins.", "As a log-normal distribution in droplet count, from which the volume in each size is recovered by weighting each count by the cube of the diameter.", "As a set of measured bins supplied by the caller, since no two produced waters carry the same shape of droplet population.", "As a concentration and a single characteristic droplet size, which is all a grade efficiency needs to be evaluated at."]'::jsonb, 0, 'Two inputs describe the whole population, and the module cuts it into volume bins so a grade efficiency can be integrated against it exactly. A single characteristic size would throw away the spread, which is the input that moves the answer hardest.'),
  ('producedwater', 'beginner', 'module', 'm03-the-droplets', 2, 'Why is droplet volume the right basis for this distribution rather than droplet count?', '["A count distribution cannot be normalised, because the number of droplets in a stream depends on the sample volume the laboratory happened to take.", "A volume basis is what makes the distribution log-normal, since a count distribution of the same population would have no closed form at all.", "A removal is a fraction of the oil and the oil is a volume, and a distribution in counts would be dominated by the finest droplets, which carry almost none of it.", "The devices in this module remove droplets one at a time, so the count is what falls and the volume is what the caller wants reported."]'::jsonb, 2, 'A very large number of very small droplets carries very little oil, so counts would put the weight of the description where the oil is not. The engine names the basis of each figure it reports so a reader never has to guess.'),
  ('producedwater', 'beginner', 'module', 'm03-the-droplets', 3, 'The UZERE inlet is d50 26 micron at sigma 0.8, on the module''s own grid of 60 bins spanning 4 sigma either side. Where does that grid reach?', '["The coarsest bin reaches 286.602586 micron and the finest starts at 1.059817303438 micron.", "The coarsest bin reaches 637.845785 micron and the finest starts at 1.059817303438 micron.", "The coarsest bin reaches 637.845785 micron and the finest starts at 26.000000 micron, which is where the median sits.", "The coarsest bin reaches 1419.551901 micron and the finest 26.000000."]'::jsonb, 1, '286.602586 micron is the coarsest bin of the same inlet at a span of 3 sigma and 1419.551901 is the coarsest at 5. The span of the grid is what sets both edges, and the median sits between them rather than at one of them.'),
  ('producedwater', 'beginner', 'module', 'm03-the-droplets', 4, 'Ask the UZERE bin set for its own volume median and it returns 26.000000 micron against a typed 26. What kind of evidence is that?', '["A calibration, because the edges of the bins were placed exactly where they had to be for the median of the bin set to return the figure the caller typed in.", "A published comparison, because a log-normal fit to measured produced water is where the relation between the two comes from.", "A coincidence of this particular grid, since a coarser or finer set of bins would return a median near 26 rather than exactly it.", "An identity, because the volume median of a log-normal distribution is its own d50, so the bin set has shown it is what it claims to be."]'::jsonb, 3, 'It is a mathematical fact about the distribution rather than an observation about produced water, it needs no published data, and it holds on every grid in the sweep from 30 bins to 600.'),
  ('producedwater', 'beginner', 'module', 'm03-the-droplets', 5, 'Move the bin count over 30, 60, 120 and 600 on the UZERE inlet. What moves?', '["The median holds at 26.000000 micron on every row and the truncated tail falls steadily as the bins are added, because a finer grid describes more of the same distribution.", "Both move a little, and the module reports the grid back on the answer so that the reader knows which resolution produced the figure.", "Neither the median nor the truncated tail moves, because the tail is a property of how far the grid reaches rather than of how finely it is divided.", "The truncated tail holds at 0.000063372072 and the median drifts, which is the quantisation a coarse grid puts into a bin median."]'::jsonb, 2, 'The median reads 26.000000 and the tail reads 0.000063372072 on all four rows. Bin count is the input an engineer is most tempted to raise when an answer looks suspicious, and raising it here moves neither of those two figures.'),
  ('producedwater', 'beginner', 'module', 'm03-the-droplets', 6, 'Hold the bin count and change the span from 3 sigma to 6. What does the truncated tail do?', '["It falls from 0.002699934563 to 0.000000001980, because a wider grid reaches further into the distribution and throws less of it away.", "It rises from 0.000000001980 to 0.002699934563, because a wider grid puts more of its bins out near the edges of the distribution where the volume in each one is thin.", "It holds at 0.000063372072 throughout, which is the analytic tail of this distribution and is a property of the spread rather than of the grid it is laid on.", "It falls to zero at a span of 6 sigma, which is why the module holds its own floor at 3 sigma and refuses below it."]'::jsonb, 0, 'The tail is the volume outside the span, so reaching further leaves less of it. The coarsest bin runs from 286.602586 micron to 3159.270855 across those same four rows, and 0.000063372072 is the tail at the default span of 4.'),
  ('producedwater', 'beginner', 'module', 'm03-the-droplets', 7, 'What happens to the volume the grid leaves outside its span?', '["It is dropped, so the bins sum to slightly less than the whole, which is why the truncated tail is reported beside the answer.", "The normalisation absorbs it, so the bins always sum to the whole, and the module reports how much was absorbed.", "It is placed in the two edge bins, which is why the coarsest bin of a narrow grid carries more volume than a wide one does.", "It is refused when it grows past a declared fraction, since a grid that throws away that much of the oil cannot be integrated against."]'::jsonb, 1, 'Reporting the tail is what lets a reader judge the grid. At the default span the truncated fraction is 0.000063372072, and the grid is reported back on the answer rather than kept as an implementation detail.'),
  ('producedwater', 'beginner', 'module', 'm03-the-droplets', 8, 'On the bin count sweep the digest divides the reported tail by twice the module''s own cdf below the span edge, and the column reads 1.000000000000 on every row. What does that rule out?', '["That the bin count moves the answer, since a column of ones across four resolutions is what an invariance looks like.", "That the module takes its cdf on the diameter rather than the volume, putting the tail on the wrong variable.", "That the truncated tail is a binning artefact, since it is exactly the analytic tail of the distribution instead.", "That the bins have been normalised, since a set of bins that did not sum to the whole would leave that column somewhere other than one."]'::jsonb, 2, 'The check compares the module against a mathematical fact about the distribution it says it is using. A grid artefact would show up in that column at once as a departure from one.'),
  ('producedwater', 'beginner', 'module', 'm03-the-droplets', 9, 'One device at a 12 micron cut, one water, and only the spread of the droplets moved. The removal runs from 84.480253 percent at sigma 0.5 to 68.402514 at sigma 1.5. Why does a wider spread treat worse?', '["A wide population has a lower median, so the same cut size sits further up the distribution and the device is asked for more than it can give.", "A wide population carries more droplets in total at the same concentration, so the device has more collisions to make in the same residence time.", "A wide population is described on a grid reaching further out, so more of its volume falls in the truncated tail and is never presented to the device.", "A wide population puts oil volume into droplets far below the cut size, and those go straight through, while the coarse end it also reaches was being caught anyway."]'::jsonb, 3, 'The median was held at 26 micron and the cut size at 12 throughout, and the grid is the module''s own default on every row. The two ends of a widening distribution do not cancel: the coarse end has nothing left to give and the fine end passes.'),
  ('producedwater', 'beginner', 'module', 'm03-the-droplets', 10, 'Read the outlet median column of that same sigma sweep: 15.793311 micron at sigma 0.5 and 5.944722 at sigma 1.5. What is it telling a designer?', '["The widest row leaves the hardest water in the table for whatever device stands downstream, and it came out of the same equipment as every other row.", "The widest row leaves the easiest water downstream, since a fine outlet median means the coarse oil has already been taken out.", "The outlet median is what the next device''s cut size should be set to, which is how a train is sized stage by stage.", "The outlet median falls because the concentration fell, so the two columns are the same fact reported in two units."]'::jsonb, 0, 'A finer outlet population is a harder duty for any device, because a cut size acts on sizes rather than on mass. The concentration and the median are different facts, and a device that removes a great deal can still leave a fine population behind.'),
  ('producedwater', 'beginner', 'module', 'm03-the-droplets', 11, 'Where does this module warn on the droplet spread, and where does it stop answering?', '["It warns outside 0.5 to 1 and refuses above 1.5, which is the widest row the digest sweeps and the last one that answers.", "It warns outside 0.5 to 1 and refuses above 2, because a wider spread than that is not what produced water carries.", "It warns above 1 only, since a tight distribution is always within what the log-normal form can describe.", "It refuses outside 0.5 to 1, because a spread outside the customary band would carry volume beyond the span the grid reaches."]'::jsonb, 1, 'The sigma of 1.5 answers and carries the warning, which is the ordinary pattern here: doubt is reported and the number still arrives, while a value the method has nothing to say about is declined by name.'),
  ('producedwater', 'beginner', 'module', 'm03-the-droplets', 12, 'What floors does this module hold under the droplet grid itself?', '["It will not describe the distribution on fewer than 30 bins, which is the coarsest row of the bin count sweep.", "It holds no floor under either, since the grid is reported back on every answer and a reader can judge it.", "It will not describe the distribution on fewer than 10 bins, nor span fewer than 3 sigma either side of the median.", "It will not span fewer than 4 sigma either side, which is the default the module uses and the span its tail is quoted at."]'::jsonb, 2, 'Both floors are declared constants, so a reader can find them in one place. 30 bins and a span of 4 are sweep rows and defaults rather than limits.'),
  ('producedwater', 'beginner', 'module', 'm03-the-droplets', 13, 'A reader has a median droplet size from a laboratory and no measurement of the spread at all. What is the honest response?', '["Use the module default, since a default that ships with the engine is the value most produced waters sit at.", "Report the concentration alone, since an answer resting on a guessed input is worth less than no answer.", "Take the spread from the outlet median of an existing device on the same stream, which fixes it by inversion.", "Run the population at the low end and the high end of what is plausible and look at both answers."]'::jsonb, 3, 'If the design decision is the same at both ends, the missing measurement does not matter. If it is not, the measurement has justified its own cost, which is a far stronger argument for a droplet sizing campaign than any assertion about one spread.'),
  ('producedwater', 'beginner', 'module', 'm03-the-droplets', 14, 'Why does this module discretise the distribution into bins at all rather than carrying it as a curve?', '["So that a device grade efficiency can be multiplied against the oil volume in each bin and summed, which makes the removal a finite sum over a grid the module reports back.", "So that the outlet of one stage can be handed to the next as a list of numbers, which is the only way a train of devices can be assembled.", "So that the truncated tail can be measured, which is the check that proves the distribution is log-normal in volume.", "So that the median can be interpolated across the bin it falls in, which a continuous curve would not allow."]'::jsonb, 0, 'The integral is what a removal is, and the bins are what make it exact on a stated grid. The outlet distribution and the reported median are consequences of having a grid rather than reasons for having one.'),
  ('producedwater', 'beginner', 'module', 'm03-the-droplets', 15, 'Which of these would tell a reader that the bin set is not what it claims to be?', '["A truncated tail that falls as the span is widened, since the analytic tail of a log-normal does not depend on the grid.", "A volume median drifting away from the typed d50 as the bin count is raised.", "A removal that falls as the droplet spread is widened at a fixed cut size, since the device has not moved.", "A coarsest bin that grows as the span is widened, since the grid would then be reaching past the distribution it describes."]'::jsonb, 1, 'The median identity is the check with nothing behind it but arithmetic. The other three are the module behaving as the sweeps in this section say it does.'),
  ('producedwater', 'beginner', 'module', 'm04-a-droplets-rise', 1, 'Everything gravity and everything centrifugal in this module comes from one balance. What is it?', '["A droplet rises because the water around it is in motion, and the balance is between that motion and the residence time it is given.", "A droplet rises because it is lighter than the water, and the drag on it balances that buoyancy.", "A droplet rises at the velocity the vessel imposes on it, and the balance is between the surface loading and the depth of the water.", "A droplet rises until it meets a droplet of its own size, and the balance is between the rate of those meetings and the flow through the vessel."]'::jsonb, 1, 'Buoyancy against drag, and nothing else. The surface loading of a vessel is what a rise velocity is later compared against, and coalescence of droplets with each other is not in this module at all.'),
  ('producedwater', 'beginner', 'module', 'm04-a-droplets-rise', 2, 'Why are the closed form and the full drag balance in this module described as two methods rather than two copies of one?', '["The closed form is the engine''s own route and the balance belongs to the oracle, so the two of them live in different files and are maintained quite separately.", "The closed form is stated for oil in water and the balance is stated for gas bubbles, so the two are never applied to the same droplet.", "The closed form carries the declared sharpness of 3 and the balance carries the derived 2, so the two produce different grade curves.", "The closed form solves in one line under the creeping flow assumption, and the balance is a damped iteration on the Schiller-Naumann drag coefficient."]'::jsonb, 3, 'Two different routes to one quantity is what makes their agreement inside the band evidence of anything. Sharpness belongs to the grade efficiency curve rather than to a rise velocity.'),
  ('producedwater', 'beginner', 'module', 'm04-a-droplets-rise', 3, 'In the UZERE water the two routes are divided on each row of the droplet sweep: 1.000088 at 5 micron and 1.785576 at 500. What does that column do?', '["It grows on every row of the table, which is the whole content of the band, since the departure tracks the Reynolds number rather than jumping at a threshold.", "It grows until the stated Reynolds limit and then holds, since the module stops applying the closed form past the edge of the band.", "It grows and then turns over, because the drag coefficient falls again once the wake behind the droplet is fully developed.", "It holds near one across the band and then rises sharply, which is the cliff the stated limit of 1 was placed at."]'::jsonb, 0, 'There is no cliff in that column and no threshold where the answer suddenly breaks. The band is a line drawn across a smooth departure, which is why the module reports the Reynolds number itself rather than only the verdict about it.'),
  ('producedwater', 'beginner', 'module', 'm04-a-droplets-rise', 4, 'At 120 micron in the UZERE water the Reynolds number is 0.274873. What do the two routes do there?', '["They agree to 8.83e-5, which is the agreement the module reports at the fine end of the same sweep.", "They differ by 78.557612 percent, which is the departure the module warns about above its stated limit.", "They already differ by 5.937008 percent, with the closed form giving the larger velocity.", "They agree exactly, because 0.274873 sits inside the stated band."]'::jsonb, 2, '8.83e-5 is the agreement at 5 micron and 78.557612 percent is the departure at 500 micron and Reynolds 19.883778. Inside the band the two routes are close rather than identical, and the departure is already several percent well before the limit.'),
  ('producedwater', 'beginner', 'module', 'm04-a-droplets-rise', 5, 'Where does this module state its closed form rise velocity to, and what does it do past that point?', '["To a Reynolds number of 1, above which it refuses, because the closed form has left the regime it was derived in.", "To a Reynolds number of 1, above which it warns and still returns the velocity.", "To a Reynolds number of 2, which is the widest departure the published rise cases in the golden file reach.", "To a droplet diameter of 120 micron, which is the coarsest row of the sweep that the module marks as in band."]'::jsonb, 1, 'The limit is declared and sits in the same frozen object as every other choice in the engine. A number just past a smooth departure is nearly as good as one just inside it, so refusing would throw away a usable answer to make a point about a boundary.'),
  ('producedwater', 'beginner', 'module', 'm04-a-droplets-rise', 6, 'The closed form gives the larger velocity on every row where the two disagree. Why does that direction earn a warning?', '["An overstated rise velocity produces an overstated cut size, so the equipment is credited with less than it does, which wastes capital on vessels nobody needed.", "An overstated rise velocity puts the droplet outside the band, so the warning is really about the Reynolds number rather than about the direction of the error.", "An overstated rise velocity makes the removal larger and the outlet median coarser at once, so two reported figures move in ways a reader cannot separate.", "An overstated rise velocity produces an understated cut size, so the equipment is credited with catching finer oil than it will, and that is the error a designer is least likely to catch."]'::jsonb, 3, 'Optimistic in the direction that matters: a faster droplet is a smaller droplet caught. A conservative error advertises itself when the equipment is built, and an optimistic one shows up as oil in the effluent.'),
  ('producedwater', 'beginner', 'module', 'm04-a-droplets-rise', 7, 'A cut size comes back with a Reynolds number beside it. What is the reader being handed?', '["A statement about the water rather than about the droplet it was computed for, so that one single figure covers every device that is ever sized on that one produced water stream.", "A check the reader has to run by hand against the stated limit, since the devices report the number without judging it.", "The evidence about that cut size''s own trustworthiness, because every device here reports the Reynolds number of its own cut droplet and warns the same way.", "The Reynolds number of the median droplet of the inlet, which is the droplet the rise velocity was reported for."]'::jsonb, 2, 'The band is a statement about the droplet and the water together, so one stream can hold droplets inside it and droplets outside it at once. The device does the judging as well as the reporting, and the warning arrives on the same return.'),
  ('producedwater', 'beginner', 'module', 'm04-a-droplets-rise', 8, 'What does the engine say when a cut droplet sits outside creeping flow?', '["That the cut droplet sits outside the creeping flow Stokes is stated for, so this cut size is optimistic.", "That the cut droplet sits outside the creeping flow Stokes is stated for, so no cut size is reported for this device.", "That the droplet Reynolds number is above its limit, without saying which assumption that limit belongs to.", "That the answer is doubtful and the reader should add margin to the vessel before using it."]'::jsonb, 0, 'The sentence carries two things a reader needs: which assumption was broken and which way the error points. A warning that only said the answer was doubtful would leave the designer guessing whether to add margin or take it away.'),
  ('producedwater', 'beginner', 'module', 'm04-a-droplets-rise', 9, 'The UZERE basin cuts at 165.003927 micron with its cut droplet at Reynolds 0.714614. Push its short-circuit allowance to 2.5 and the cut becomes 213.019154. What comes back with the second answer?', '["One warning and the answer, naming the allowance, since the band on the allowance is the only thing that moved.", "Two warnings and the answer: the allowance is outside its customary band, and the cut droplet is outside creeping flow.", "A refusal, because an allowance of 2.5 puts the cut droplet past the Reynolds limit the module states its rise velocity to.", "Two warnings and a withheld cut size, because a figure outside the band is reported as null rather than as an optimistic number."]'::jsonb, 1, 'Two warnings, one answer, and the answer still arrives. The first basin returns no warning of any kind, which is what makes the pair worth reading together.'),
  ('producedwater', 'beginner', 'module', 'm04-a-droplets-rise', 10, 'One published basin row in the golden file cuts at 188.080643 micron with a golden Reynolds number of 1.851949, past the stated limit. Why is it there?', '["The published case was measured on a real basin and the module has to reproduce it whether or not it sits in band.", "The row exists to fix the limit itself, since the band edge is placed where the published cases stop agreeing.", "A gate that only ever sees cases inside a band cannot tell whether the band is being policed at all.", "Three of the four basin rows sit outside the band, so the file measures the module mostly where it warns."]'::jsonb, 2, 'Testing the comfortable cases proves the arithmetic and testing an uncomfortable one proves the guard. 1 published row across the basin, plate and rise groups sits outside the band on purpose.'),
  ('producedwater', 'beginner', 'module', 'm04-a-droplets-rise', 11, 'A design rests on a cut size whose droplet is outside the creeping flow band. What are the honest moves?', '["Make the device larger until the cut droplet falls back inside the band, or get a rise velocity from a method that does not assume creeping flow.", "Apply a margin to the cut size in proportion to the Reynolds number reported beside it, which is the whole reason that figure is printed on the same return as the answer.", "Take the answer as it stands, since the module warned rather than refusing and a warning is advice rather than a finding.", "Report the cut size with the warning attached and let the next reader decide what the figure is worth."]'::jsonb, 0, 'The equipment is being credited with catching finer oil than it will, so the real performance is worse than the printed one. Carrying the optimistic figure forward without saying so is the one option the warning exists to prevent.'),
  ('producedwater', 'beginner', 'module', 'm04-a-droplets-rise', 12, 'A 100 micron droplet in the UZERE water rises at 0.001091782327 m/s. What is recovered from that answer, and how?', '["The Reynolds number of that droplet, which is what the same group reduces to once the diameter and the velocity have both been put into it.", "The density difference of 142.391799 kg/m3, which is the only unknown left once the diameter and the velocity are both in hand.", "The declared sharpness of 3, which the rise velocity carries into every grade efficiency curve the gravity devices use.", "The 18 of the Stokes group, from gravity times the diameter squared times the density difference, over the viscosity times that velocity."]'::jsonb, 3, 'The group comes to 18.000000000000 and nothing typed it into the answer. The viscosity and the density difference are inputs to that velocity rather than things recovered from it.'),
  ('producedwater', 'beginner', 'module', 'm04-a-droplets-rise', 13, 'The UZERE median droplet rises at 0.000073804485 m/s at a Reynolds number of 0.002796. What should a reader do with those two figures?', '["Read the velocity as the treating answer for this stream, since it belongs to the median droplet and half of the oil volume in the water sits above that one size.", "Read the velocity as the reason a gravity vessel has to be large, and the Reynolds number as the evidence that the velocity beside it can be believed.", "Read the Reynolds number as a property of the water itself, so that every droplet carried in this particular stream can be taken as sitting inside the stated band.", "Read the velocity as the loading the basin has to be designed to, since a droplet rising that slowly sets the flow the vessel can take."]'::jsonb, 1, 'Nothing has been removed from anything yet: a rise velocity says how fast a droplet travels and says nothing about whether the vessel gives it the room. The Reynolds number belongs to the droplet and the water together.'),
  ('producedwater', 'beginner', 'module', 'm04-a-droplets-rise', 14, 'Why does a single produced water stream have many rise velocities rather than one?', '["The velocity depends on where in the vessel the droplet sits, so the figure reported is an average over the depth of the water.", "The velocity changes as the droplet rises, since the drag falls away once the droplet leaves the bulk and nears the surface.", "A population of droplets has a velocity for each size, coarse ones rising faster and fine ones slower, which is why a device removes a fraction rather than everything.", "Each device computes its own rise velocity from its own geometry, so a stream has as many velocities as it has stages."]'::jsonb, 2, 'The reported figure belongs to the median droplet of that particular stream. Coarse droplets in the same water rise faster and fine ones slower, and the whole shape of a grade efficiency curve follows from that.'),
  ('producedwater', 'beginner', 'module', 'm04-a-droplets-rise', 15, 'A rise velocity comes back far from what the water and the crude would suggest. What is it most useful for?', '["As a sanity check on the inputs, because a density or a temperature typed wrong is much easier to see here than three devices further down a train.", "As a signal that the droplet sits outside the band, since a velocity that surprising is usually a Reynolds number problem.", "As a reason to move to the full drag balance, which does not carry the assumption the closed form makes.", "As the figure to quote to a vendor, since a rise velocity is the one number in this chain that does not depend on equipment."]'::jsonb, 0, 'Every figure below it in the chain consumes it, and each one prints normally on the way down. The band question is answered by the Reynolds number reported beside it rather than by the velocity looking odd.'),
  ('producedwater', 'beginner', 'module', 'm05-the-gravity-devices', 1, 'What does an API 421 basin remove, in one sentence, and what happens to the depth when that sentence is written as algebra?', '["It removes the droplet that can rise the depth of the water in the time the water spends in the basin, and the depth is what the answer then divides by.", "It removes the droplet that can rise the depth of the water in the time the water spends in the basin, and the depth cancels out.", "It removes every droplet coarser than the median of the inlet population, and the depth sets how much of the distribution that is.", "It removes the droplets that reach the surface before the residence time runs out, and the depth enters through the residence time alone."]'::jsonb, 1, 'A droplet has further to rise in a deeper basin and is given proportionally longer to do it, so the depth leaves the expression entirely. What is left is the flow over the plan area.'),
  ('producedwater', 'beginner', 'module', 'm05-the-gravity-devices', 2, 'What is the surface loading of a basin, and what is done to it before a cut size comes out?', '["The flow divided by the plan area, multiplied by an allowance for turbulence and short-circuiting, and the rise balance is then inverted at the result.", "The flow divided by the cross section the water actually moves through, which is compared against the fixed velocity limit before any cut size at all is reported.", "The flow divided by the plan area, multiplied by the plate efficiency factor of 0.7, which is the fraction of that area that settles.", "The rise velocity of the median droplet, multiplied by the residence time, which gives the depth a droplet can clear."]'::jsonb, 0, 'The loading has units of velocity and it is the rise velocity a droplet must beat to get out. The flow over the cross section is the horizontal velocity, which is a separate check, and the efficiency factor belongs to a plate pack.'),
  ('producedwater', 'beginner', 'module', 'm05-the-gravity-devices', 3, 'The UZERE basin is run at two water depths, 1.4 m and 0.9 m, and everything else is held. What happens?', '["The cut size falls from 165.003927 micron to a finer figure, because a shallower basin gives every droplet less distance to travel.", "The cut size is 165.003927 micron on both rows and the residence time is 706.471546 s on both, because the flow and the plan area did not move.", "The cut size is 165.003927 micron on both rows, and the horizontal velocity rises from 0.014154851756 to 0.022018658288 m/s.", "The cut size coarsens because the residence time falls from 706.471546 s to 454.160279 s, and the warning on the second row says so."]'::jsonb, 2, 'The plan area and the flow are what the cut size is built from, and neither moved. The residence falls with the depth because the same flow through a smaller cross section moves faster and stays a shorter time, and the shallow row carries the velocity warning.'),
  ('producedwater', 'beginner', 'module', 'm05-the-gravity-devices', 4, 'Why does a basin need a horizontal velocity check at all when its cut size is acceptable?', '["The horizontal velocity is what sets the residence time, so a fast basin gives its droplets too little time to reach the surface at all.", "The check is what fixes the plan area, since a basin sized on its cut size alone has no constraint on its length or its width.", "A fast basin carries the coarse droplets past the outlet before they can be skimmed, so the removal falls even where the cut size holds.", "Oil that has already risen to the surface is dragged back into the bulk and carried out when the water underneath moves fast enough, which a cut size calculation cannot see."]'::jsonb, 3, 'The device does the separation and then undoes it, which is a separate failure with a separate criterion. The cut size question is only about whether a droplet can reach the top.'),
  ('producedwater', 'beginner', 'module', 'm05-the-gravity-devices', 5, 'What does this module say about the API 421 horizontal velocity rule it applies?', '["That the rule is applied in full, with both halves reported, since the standard states the check as a single limiting velocity.", "That only the fixed velocity half of the rule is applied here, marked on every return that carries the check.", "That the rule is customary rather than published, so the module holds it as a warning and states no source for the figure.", "That the second half of the rule is applied and the fixed half is not, since a multiple of the design rise velocity is the tighter of the two."]'::jsonb, 1, 'The standard limits the horizontal velocity to the lesser of a fixed velocity and a multiple of the design droplet rise velocity, and the second half is not in this repository. A basin that passes this check has passed half a rule, and the return says so rather than reporting a clean verdict.'),
  ('producedwater', 'beginner', 'module', 'm05-the-gravity-devices', 6, 'Four basin footprints are swept from 12.000000 m2 of plan area to 80.000000, and the cut size falls from 242.879204 micron to 94.066711. The cut divided by the square root of the loading reads 3706.616030 on all four rows. What does that constant column establish?', '["That the cut size goes as the square root of the surface loading exactly, with no other dependence hiding in the flow or the dimensions.", "That the plan area is the only input the cut size responds to, since every other dimension of the basin has been shown to cancel.", "That the module reproduces the four published basin cases, since a constant ratio between the engine and a golden is what agreement looks like.", "That the cut size and the loading are the same quantity in different units, which is why the ratio between them does not move."]'::jsonb, 0, 'A column that ought to hold still across a sweep, and does, is a statement about the form of the relationship. A hidden extra term in the flow or in the dimensions would show up as a drift without anybody reading the source.'),
  ('producedwater', 'beginner', 'module', 'm05-the-gravity-devices', 7, 'What does the constant column in that sweep cost a designer who wants a finer cut?', '["Halving the cut size costs twice the basin, since the loading and the cut size move together.", "Halving the cut size costs sixteen times the basin, because the driving force enters squared as well.", "Halving the cut size costs four times the basin.", "Halving the cut size costs nothing in area and is bought by making the basin deeper instead."]'::jsonb, 2, 'The cut size carries the square root of the loading, so the area carries the square of the improvement. Gravity separation runs into economics very quickly for that reason, and the depth does not enter the cut size at all.'),
  ('producedwater', 'beginner', 'module', 'm05-the-gravity-devices', 8, 'The short-circuit allowance F is swept from 1 to 2.5 and the cut size runs from 134.725142 micron to 213.019154. What is the allowance for, and which way does raising it move the answer?', '["It stands for the fraction of the plan area that actually settles, and raising it coarsens the cut size.", "It stands for the turbulence a jetting inlet creates, and raising it refines the cut size by mixing the droplets across the depth.", "It stands for the margin between the design rise velocity and the horizontal velocity limit, and raising it refines the cut size.", "It stands for the flow that reaches the outlet sooner than a uniform plug would, and raising it coarsens the cut size."]'::jsonb, 3, 'Real vessels do not cross as a uniform plug at one velocity, and the allowance raises the rise velocity a droplet must achieve, which coarsens the cut. It is the one place in this device where engineering judgement enters an otherwise closed calculation.'),
  ('producedwater', 'beginner', 'module', 'm05-the-gravity-devices', 9, 'An allowance of 1 returns a cut size of 134.725142 micron with a warning, and an allowance of 0 is refused. Why are the two treated differently?', '["An allowance of 1 is inside the customary band of 1.3 to 1.8 and an allowance of 0 is outside it, which is the only distinction the module draws.", "An allowance of 1 is answerable and doubtful, and an allowance of zero or less is outside what the quantity means at all.", "An allowance of 1 produces a cut droplet inside the creeping flow band and an allowance of 0 produces one outside it.", "An allowance of 1 is the module''s own default, so it is reported with a note, while any value a caller supplies is checked against the band."]'::jsonb, 1, 'The engine says that F must be positive and that an F of zero or less leaves the separator undefined. The default is 1.5, the customary band is 1.3 to 1.8, and 1 sits outside that band and still answers.'),
  ('producedwater', 'beginner', 'module', 'm05-the-gravity-devices', 10, 'What does this module do with an allowance of 6?', '["It refuses, saying that F is a turbulence allowance customarily between 1.3 and 1.8, that this module holds it to 5, and that this is 6.", "It answers with a warning that the allowance is outside its customary band, as it does at 1 and at 2.5.", "It refuses, saying that an allowance above the customary band would put the cut droplet outside creeping flow.", "It answers and marks the velocity rule as incomplete, because the allowance has left the range the published half of the rule is stated over."]'::jsonb, 0, 'The refusal states what the quantity is before it states what was wrong with the input, which is the shape every guard in this engine takes. A refusal that only said the input was invalid would leave the caller guessing at the range.'),
  ('producedwater', 'beginner', 'module', 'm05-the-gravity-devices', 11, 'A pack of 30 plates of 3 m2 reaches an effective area of 63.000000 m2. How was that figure built, and what does it change about the basin argument?', '["The projected plate area times the plate count times the short-circuit allowance of 1.5, which is what a pack of plates is credited with.", "The plan area of the vessel times the plate count, which is why a pack in a small box can reach the area of a very large basin.", "The projected plate area times the plate count times a factor of 0.7, and it changes the area the flow is divided by while leaving the physics alone.", "The projected plate area times the plate count, with the 0.7 applied afterwards to the cut size rather than to the area."]'::jsonb, 2, 'Same physics, more area. The efficiency factor is the fraction of the projected area that actually settles, it is declared with no source in this repository, and it sits in the middle of the chain where the area, the design rise velocity and the cut size all move with it.'),
  ('producedwater', 'beginner', 'module', 'm05-the-gravity-devices', 12, 'A plate pack is swept from 10 plates to 120 and the cut size falls from 149.908299 micron to 43.274798. What is the limit of that as a strategy?', '["The cut size stops improving once the effective area passes the plan area of the vessel, which is where a pack runs out of room.", "Stacking more plates keeps working and keeps costing, and no arrangement of settling surfaces reaches the finest droplets a produced water stream carries.", "The plate count enters the cut size linearly, so a pack has to be doubled in size for each micron of improvement.", "The pack begins to carry a warning past 60 plates, because the channels have become too narrow for the creeping flow assumption."]'::jsonb, 1, 'The effective area runs from 21.000000 m2 to 252.000000 across that sweep and the cut size falls with the square root of the loading, exactly as the basin does. Devices that go further stop relying on gravity alone.'),
  ('producedwater', 'beginner', 'module', 'm05-the-gravity-devices', 13, 'The published plate cases carry a channelHeightIndependence figure, and it comes out at 2.21e-14, 2.19e-14 and 2.15e-14. What is being proved?', '["That the engine and the oracle agree on the plate cut size to that many digits, which is the gap between two independent methods.", "That the plate efficiency factor of 0.7 has been validated, since the three cases were run at different plate spacings.", "That the channel height is an input the module ignores, which is why a caller cannot supply one at all.", "That a plate pack cut size does not depend on how the pack is sliced into channels, which follows from what the device is."]'::jsonb, 3, 'The oracle marches the same pack at two different channel heights and reports the difference. The settling area is the same either way, so the requirement follows from the device rather than from a published comparison, and those three figures are the proof of it rather than the claim.'),
  ('producedwater', 'beginner', 'module', 'm05-the-gravity-devices', 14, 'The four published basin cases come back at 44.331033, 99.128864, 188.080643 and 54.820774 micron against the golden values. What does the ratio column of that table read, and what does the set of cases show?', '["It reads 1.000000000000 on every row, and the four are a spread of inputs rather than one comfortable case repeated.", "It reads 1.000000000000 on every row, because the golden values are the engine''s own answers recorded back into the file.", "It reads close to one, with the departure set by the Monte Carlo the oracle marches each case with.", "It reads 1.000000000000 on three rows and drifts on the fourth, which is the row whose cut droplet sits outside the band."]'::jsonb, 0, 'The engine reproduces each published value to the digits printed, and the four cases differ in the flow and in every dimension of the vessel. A golden holding the engine''s own answers back would agree with anything the engine later did.'),
  ('producedwater', 'beginner', 'module', 'm05-the-gravity-devices', 15, 'A device is applied to the UZERE water at cut sizes from 30 micron down to 2, and the removal runs from 44.236922 percent to 99.398720 while the outlet median falls from 16.943389 micron to 4.880416. What are those two columns together saying?', '["A tighter cut removes more of the oil and leaves a coarser population behind, since the fine droplets are the ones a low cut size takes out.", "A tighter cut removes more of the oil and leaves the same population behind, since a removal is a fraction of the volume and not of the sizes.", "A tighter cut removes more of the oil and leaves a finer population behind, so the water each stage hands on is harder than the water it was given.", "The outlet median is what the removal is computed from, so the two columns are the same figure reported twice."]'::jsonb, 2, 'A cut size acts on sizes, so the coarse end goes first whatever the cut is set to. Below a floor the module stops reporting an outlet median at all, because the shape of numerical dust means nothing.'),
  ('producedwater', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Step one of the UZERE reading turns 28000 bwpd into 0.051523660393 m3/s. What is that step, and why is it worth naming?', '["The first physical calculation, since the flow is what the surface loading of the basin is built from and nothing above it is physics.", "A conversion the caller has to make, since this module takes a rate in barrels a day and reports back in the same unit.", "Bookkeeping in exact units, since the barrel is exactly 0.158987294928 m3 and every device answer below is in the units this step produced.", "A declared conversion of this module, pinned in the frozen object with the rest of the chosen values in it."]'::jsonb, 2, 'The rate becomes a volumetric flow before any physics happens. The exact barrel is a definition rather than a choice, and the Suite layer does the conversion so that everything downstream is in one system of units.'),
  ('producedwater', 'beginner', 'module', 'm06-the-associate-reading', 2, 'Steps two to five of the chain produce a viscosity, a brine density, a crude density and a difference. What has not been mentioned yet, and why does that matter?', '["No dimension of any vessel, which is why the hardness of a duty can be judged before a catalogue is opened.", "No input the caller typed, since those four steps are computed from the flow step one produced.", "No temperature, since temperature enters only where the crude is thinned and the rest of the chain is isothermal.", "No flow rate, since the fluid properties are intensive and the rate enters only at the device."]'::jsonb, 0, 'The fluid properties are settled before any equipment is chosen. The temperature is the input three of those four steps consume, and the flow arrived at step one.'),
  ('producedwater', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Step six asks how fast the UZERE median droplet rises. What comes back, and what does the second figure add?', '["0.000073804485 m/s at a Reynolds number of 0.002796, and the Reynolds number is the fraction of the population sitting inside the band.", "0.000073804485 m/s at a Reynolds number of 0.002796, and the Reynolds number is what says the velocity beside it can be believed.", "0.001091782327 m/s at a Reynolds number of 0.002796, which is the velocity of the median droplet of this stream.", "0.000073804485 m/s with no Reynolds number, since the number is reported by the devices rather than by the rise velocity."]'::jsonb, 1, '0.001091782327 m/s belongs to a 100 micron droplet in the same water. The Reynolds number is a property of that droplet in that water, and it sits far below the stated limit of 1 here.'),
  ('producedwater', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Step nine reports that the basin removes 3.284882 percent of the oil in this water. Why is the figure so small?', '["The basin removes only the oil that has risen by the time the residence of 706.471546 s runs out, and the rest is carried over.", "The removal is quoted over the whole train rather than over the basin alone, so the plate pack downstream carries most of it.", "The inlet is only 650 ppm, so there is little oil in the water for the basin to take out in the first place.", "The basin cuts at 165.003927 micron and the droplets arrive at a median of 26, so nearly all the oil volume is in droplets it cannot catch."]'::jsonb, 3, 'A cut size is the droplet the device removes half of, so a population whose median sits far below it is barely touched. A removal is a fraction of whatever oil is present, so the inlet concentration does not set it.'),
  ('producedwater', 'beginner', 'module', 'm06-the-associate-reading', 5, 'The basin is left exactly as it is. What change in the water would raise that removal?', '["A higher oil concentration at the same droplet sizes, since there is then more oil for the device to work on.", "A coarser droplet population, because the removal depends on the droplet sizes against the cut size.", "A finer droplet population, since fine droplets are the ones a basin holds on to best.", "The same droplets at a higher water rate, since a faster basin presents more oil to the surface in the same time."]'::jsonb, 1, 'Read the sweep of cut sizes against this water the other way round: what matters is where the population sits against the cut. A higher rate raises the surface loading and coarsens the cut size, so it moves the removal the other way.'),
  ('producedwater', 'beginner', 'module', 'm06-the-associate-reading', 6, 'How does the engine turn a cut size into the 3.284882 percent, and why does it insist on a droplet median and a spread first?', '["It multiplies the grade efficiency at every bin by the oil volume in that bin and sums, so the answer depends on the device and the water together.", "It reads the removal for that cut size from the grade efficiency curve at the median droplet size of the inlet population.", "It compares the cut size with the median and takes the fraction of the distribution above it, which is why the spread is needed.", "It integrates the grade efficiency over the droplet sizes with each size weighted equally, which is what the fixed grid is for."]'::jsonb, 0, 'A coarse bin gives up nearly all of its volume, a bin at the cut size about half of it, and a fine bin almost none. Weighting sizes equally would be a count basis, and a single figure read at the median would throw the whole distribution away.'),
  ('producedwater', 'beginner', 'module', 'm06-the-associate-reading', 7, 'Step ten gives the plate pack a cut size of 86.549597 micron on the same water the basin cut at 165.003927. What did the change?', '["The driving force, since a pack of plates presents its droplets to a settling surface that is inclined rather than horizontal.", "The residence time, since the water inside a plate pack is held a great deal longer than the water in a basin of the same duty.", "The allowance, since a plate pack carries a smaller short-circuit factor than an open basin does.", "The area the flow is divided by, since the pack reaches an effective area of 63.000000 m2 where the basin has its footprint."]'::jsonb, 3, 'The water did not change between those two answers. Both devices invert the same balance at the design rise velocity, and the only thing that moved was what the flow was divided by.'),
  ('producedwater', 'beginner', 'module', 'm06-the-associate-reading', 8, 'Step eleven puts the UZERE stream through both devices. What comes out?', '["567.644189 ppm from the 650 ppm that arrived, which is the basin removal and the pack removal added together.", "The 3.284882 percent of the basin multiplied by what the pack removes, which is how two stages in series compound.", "567.644189 ppm from the 650 ppm that arrived, which is 12.670125 percent of the oil removed.", "650 ppm still, since neither device cuts near the 26 micron median."]'::jsonb, 2, 'The train reports its own outlet and its own overall figure. Adding two stage removals counts oil that was gone before the second device saw it, and multiplying two fractions measured on the raw stream credits the second device with performance it cannot reach.'),
  ('producedwater', 'beginner', 'module', 'm06-the-associate-reading', 9, 'Step twelve reports the droplet median falling from 26.000000 micron to 23.018983. What did that?', '["The basin and the pack took the coarse end of the population, which is what a cut size does, so what is left is finer.", "The devices removed oil evenly across the sizes, so the median fell in proportion to the concentration.", "The two medians are measured differently, the first typed and the second read off the bins, so part of the fall is the change of basis.", "The grid was renormalised after each stage, which moves the median across the bin it falls in."]'::jsonb, 0, 'Both medians are the volume median of the same bin set and the module says so on its own return, which is what makes them comparable. A device that removed a uniform slice of every size would leave the median where it was.'),
  ('producedwater', 'beginner', 'module', 'm06-the-associate-reading', 10, 'Why can the two stage removals of this train not be added together?', '["Each figure is computed on a different droplet grid, so the two are not measured on a common basis.", "Each figure is a percentage of what arrived at that stage rather than of what entered the train.", "The second stage removes some of the oil the first stage had already taken out, so the overlap would be counted twice.", "The percentages are volume fractions and the overall figure is a mass fraction, so they cannot be combined without a density."]'::jsonb, 1, 'Adding them counts oil that was gone before the second device saw it. One grid runs through the whole train, and the removals are fractions of the oil throughout.'),
  ('producedwater', 'beginner', 'module', 'm06-the-associate-reading', 11, 'The plate pack alone on the raw UZERE water removes 11.315691 percent, and compounding that with the basin predicts 14.228866 percent where the train reports 12.670125. Why does that compounding overstate the train?', '["The product ignores the oil in the truncated tails of the grid, which the normalisation absorbs at each stage.", "The product is right only where both devices carry the same sharpness, and these two carry different ones.", "The coupling: in the train the pack works on the basin''s residue, which is finer by construction, so its raw figure credits it with coarse oil already taken out.", "The product is right only when the device with the larger removal comes first, and in this train the basin comes first although it removes the smaller share of the two."]'::jsonb, 2, 'Compounding the train''s OWN stage figures, 3.284882 and 9.704008 percent, gives 12.670125 exactly, because each is a fraction of the water that reached its stage. Both of these devices carry the declared sharpness of 3.'),
  ('producedwater', 'beginner', 'module', 'm06-the-associate-reading', 12, 'What does this engine actually pass from one stage to the next?', '["The outlet concentration of the stage, out of which the next stage rebuilds a droplet distribution at the same median and the same spread.", "The cut size of the stage, so that the next device can be compared against what the last one achieved.", "The removal fraction of the stage, which the train then compounds into an overall figure at the end.", "The outlet bin distribution of the stage, normalised by the volume that survived it, with the concentration as a scaling on it."]'::jsonb, 3, 'The distribution is the state carried down the train and the concentration is a scaling on it. That coupling is the whole point of a train, and it is exactly what a table of fixed efficiencies throws away.'),
  ('producedwater', 'beginner', 'module', 'm06-the-associate-reading', 13, 'The chain is finished and the engine is asked for a verdict. What does it return?', '["Null, with the reason that no discharge specification was given.", "Null, with the reason that one of the two stages of this train did not run to completion on the stream it was given.", "A pass, since the outlet is below the figure the module holds for produced water.", "A refusal, since a verdict asked for without any specification behind it is a question this method has no way of answering."]'::jsonb, 0, 'The computation ran in full and only the judgement was declined, which is a withheld verdict rather than a refusal. A verdict needs a specification supplied by the caller, and that is the person who knows the licence, the receiving environment and the regulator.'),
  ('producedwater', 'beginner', 'module', 'm06-the-associate-reading', 14, 'A studio screen shows that blank verdict. What has the reader actually been told, and what would painting it red tell them instead?', '["That the train ran and did not reach the outlet the module holds for it, where a red field would say the same thing more loudly.", "That the engine could not compute the outlet, where a red field would correctly report a computation that did not happen.", "That an input is missing and should be supplied, where a red field would say the train had failed.", "That the verdict is being withheld until every stage of the train has run, where a red field would report a skipped stage."]'::jsonb, 2, 'A blank verdict is not a failure and it is not a pass. It is an absence of input, and the correct response is to supply the input rather than to interpret the silence.'),
  ('producedwater', 'beginner', 'module', 'm06-the-associate-reading', 15, 'Somebody quotes the 3.284882 percent as the removal of an API 421 basin. What is wrong with that?', '["It is a property of the train rather than of the basin, since the figure was computed with the plate pack in place downstream.", "It is a property of this basin on this water at this droplet distribution, and a stream with coarser droplets gives a different figure out of the same vessel.", "It understates the basin, since the percentage on a steady sample is quoted before the short-circuit allowance has been applied.", "It is a property of the grid rather than of the device, since the removal is read off the bin the inlet median falls in."]'::jsonb, 1, 'Nothing in this module is a fixed removal efficiency, which is why the same device on finer water performs worse. The stage figure is the basin alone, and the allowance is already in the cut size.'),
  ('producedwater', 'beginner', 'final', null, 1, 'A device is moved from a stream at one droplet median to a stream at a finer one, and nothing about the equipment changes. What does this module say happens to its removal?', '["It holds, because a cut size is a property of the device and the removal is read off the grade curve at that cut size.", "It falls, because the cut size stays where the geometry and the fluids put it while more of the oil volume now sits below it.", "It rises, because a finer population is spread over more bins of the grid and the integral reaches further into it.", "It cannot be said, because a removal needs a measured efficiency for that device on that water before it can be reported."]'::jsonb, 1, 'The same device on finer water performs worse, which is what actually happens and is the whole difference between this engine and a lookup table.'),
  ('producedwater', 'beginner', 'final', null, 2, 'The natural logarithm of two, 0.693147180560, turns up in this module. Which of the four kinds of number is it?', '["Derived, because a cut size is where half the volume goes and half survives, so the log of two falls out of the arithmetic.", "Declared, because it sits in the frozen object with the rest of the values the module chose rather than computed.", "Calibrated, because it was chosen so that a device at the module''s own defaults cuts where such devices are customarily credited.", "Held for literature, because no publication in this repository states the fraction a cut size is defined at."]'::jsonb, 0, 'There is nothing to check in a derived number because it follows from something else on the page. Exactly one calibration exists in this module and it is not this.'),
  ('producedwater', 'beginner', 'final', null, 3, 'Three of this module''s callable exports sit outside the error contract the other thirteen carry. Why?', '["They are the frozen exports rather than functions, so there is no call for an error contract to apply to.", "They are guaranteed to answer for any input at all, so no state exists that they would have to decline.", "They are helpers with nowhere to put an error key, so each one answers a question it cannot take with a bare NaN.", "They raise rather than return, so a caller has to handle their trouble in a different way from the way the rest of this module reports it."]'::jsonb, 2, 'Nothing in this module is thrown. Those three are helpers, and whichever export wrapped one of them is what names the offending input on the way back out.'),
  ('producedwater', 'beginner', 'final', null, 4, 'This module carries no re-entrainment model at all, and a basin still gets a horizontal velocity check because of re-entrainment. How do those two facts sit together?', '["The check is the re-entrainment model, expressed as a limiting velocity rather than as a rate, which is why the module reports it as a warning.", "The check applies to the plate pack and the basin alike, so the module covers re-entrainment wherever a surface holds separated oil.", "The check replaces the removal for a basin that fails it, which is how the module accounts for oil that is dragged back in.", "The check is a criterion on the vessel rather than a model of oil going back into the water, and nothing in the reported removal accounts for oil that is re-entrained."]'::jsonb, 3, 'Faster flow re-entrains oil the basin has already separated, which is what the velocity limit is for. The removal is the grade efficiency integrated against the droplets and carries nothing else.'),
  ('producedwater', 'beginner', 'final', null, 5, 'Which of these is a warning in this module rather than a refusal or a withheld verdict?', '["An object carrying a named error string and nothing at all that could pass for an answer, after an allowance of zero was supplied to a basin.", "A train that ran completely, with every concentration reported and the pass or fail left as null.", "A bare NaN out of one of the helpers, which whichever caller wrapped it then turns into a sentence naming the input that caused it.", "A cut size reported in full, with a note attached saying the droplet at that size has left the band the closed form is honest in."]'::jsonb, 3, 'A warning withholds nothing: the figure is reported and something is said about it at the same time. The other three are the two ways of not answering and a helper with no answer to give.'),
  ('producedwater', 'beginner', 'final', null, 6, 'The Produced Water Treatment Studio builds a train of up to three stages over one water stream. What does it report as it goes?', '["What each stage removes, what it costs to build, and what the whole train would cost to run for a year.", "What each stage removes, what the droplets left look like, and what comes out of the end.", "What each stage removes, how much oil leaves in its reject, and what that recovered oil is worth.", "What each stage removes, how long its media lasts before a backwash, and when the next one falls due."]'::jsonb, 1, 'No cost, no reject or oil recovery balance, no fouling over time and no backwash cycle is in this module. The droplets left are half of the answer, because they are what the next stage has to treat.'),
  ('producedwater', 'beginner', 'final', null, 7, 'A vendor offers a curve for the probability that a droplet colliding with a bubble sticks. What does this module let them do with it, and what does it say about its own figure?', '["The figure is an input, so a caller can supply their own, and the module''s own 0.01 is a calibration with no derivation behind it.", "The figure is fixed in the declared object, so a vendor curve cannot be applied without editing the module itself.", "The figure is derived from the interception law, so a vendor curve would contradict the physics the module states.", "The figure is held for literature, so the module refuses to compute anything at all until a caller supplies one."]'::jsonb, 0, 'It is the one number in this module with no derivation of any kind. It was chosen so a cell at the module''s own defaults lands where flotation is customarily credited, and nothing in this course presents it as published.'),
  ('producedwater', 'beginner', 'final', null, 8, 'Salinity acts on two of the properties this course runs on. Which two, and in which direction does each go?', '["It thickens the water and it makes the crude heavier, so both fluids move together and the driving force is left where it was.", "It thickens the water and it makes the water heavier, so droplets rise more slowly and the difference against the oil grows.", "It thickens the water alone, since the brine density in this module comes from the temperature fit and nothing else.", "It makes the water heavier alone, since the viscosity correction is applied to the crude rather than to the brine."]'::jsonb, 1, 'At 41 C the viscosity runs from 0.000639217342 Pa.s at 0 ppm TDS to 0.000961382883 at 280000, and the brine density carries a declared slope of 700 on the mass fraction. Nothing salinity does reaches the crude.'),
  ('producedwater', 'beginner', 'final', null, 9, 'A brine at 53 C and 15000 ppm TDS comes back at 997.174641 kg/m3 against a fresh water figure of 986.674641 at the same temperature. What is the difference between those two?', '["The temperature term alone, since the salinity is applied to the fresh figure as a multiplier rather than as an addition.", "The salinity term alone, since the fresh figure is what the temperature fit gives before any dissolved solids are added.", "The two terms together, since both the temperature and the salinity differ between a fresh water fit and a brine.", "The declared reference water of 999 kg/m3, against which both of those densities are stated."]'::jsonb, 1, 'Temperature sets the fresh water density and salinity adds to it, so holding the temperature isolates what the salt is worth. The reference water of 999 belongs to the crude density chain.'),
  ('producedwater', 'beginner', 'final', null, 10, 'What is the declared reference water of 999 kg/m3 for?', '["It is the fresh water density that the brine fit is stated against, before the salinity slope has been applied to it at all.", "It is the density this module compares an oil against when it is deciding whether that oil will rise at all.", "It is the water the droplet distribution is described in, which is why the bins are volume bins.", "It is the water the specific gravity from API gravity is taken against, on the way to a crude density."]'::jsonb, 3, 'A degree API becomes a specific gravity at 60 F, the specific gravity is taken against that reference water, and the result is thinned by temperature at a declared rate. Whether an oil rises is settled against the brine density of the actual stream.'),
  ('producedwater', 'beginner', 'final', null, 11, 'A 46 API crude at 41 C comes out at 782.203875 kg/m3, and against the UZERE brine that is a difference of 253.057299 kg/m3. What does the difference do?', '["It sets the removal, since the grade efficiency curve is evaluated against that difference at every single bin of the droplet distribution.", "It sets the residence time a device has to provide, since a lighter oil needs longer in the vessel to reach the surface.", "It fixes the short-circuit allowance, which is what carries the density difference into the API 421 calculation.", "It is the entire driving force for every gravity and centrifugal device in this module, and it is settled before any equipment is chosen."]'::jsonb, 3, 'Buoyancy is what that subtraction measures. No selection of equipment makes it larger, because it belongs to the two fluids, and a removal comes from the grade curve against the bins instead.'),
  ('producedwater', 'beginner', 'final', null, 12, 'The fresh water viscosity fit in this module has a coefficient, a numerator and an offset. What is their status?', '["All three are derived from the temperature dependence of the water density, so there is nothing left to validate.", "All three were fitted to the published viscosity data this repository carries for fresh water over the stated range.", "All three are declared and exported, so a reviewer can find them in one place, and this repository carries nothing to check them against.", "All three are held for literature, which is why the module states the range the fit holds over rather than the constants."]'::jsonb, 2, 'The engine says about itself that pinning such a value is all any gate can do. What a declaration buys is that moving one becomes a reviewed act instead of a silent one.'),
  ('producedwater', 'beginner', 'final', null, 13, 'The crude in this module thins with temperature at 0.0007 for each degree. What must a reader know about that figure?', '["It is declared, applied at that one rate to every crude the module is given, with no publication in this repository to check it against.", "It is derived from the same standard relation that turns a degree of API gravity into a specific gravity at 60 F, and carries nothing chosen in it at all.", "It is fitted to whatever assay the caller supplies, which is why the crude density is reported at treating temperature.", "It is held for literature, which is why a caller has to supply an expansion rate before a crude density comes back."]'::jsonb, 0, 'A declared value is customary or chosen and the module keeps it in one frozen place so that moving it is a reviewed act. Held for literature means the module states an absence instead, and nothing here is absent in this chain.'),
  ('producedwater', 'beginner', 'final', null, 14, 'An answer looks suspicious and an engineer raises the bin count from 60 to 600. What does that do to the volume median and the truncated tail the bin set reports?', '["Nothing to either of them, since the median is an identity of the distribution and the tail is set by how far the grid reaches.", "It moves the median closer to the typed d50, since a coarse grid carries a quantisation that a finer grid removes.", "It shrinks the truncated tail, since a grid that has been cut into more bins reaches further out into the distribution.", "A refusal, since this module holds the bin count to the 60 it defaults to and declines anything else."]'::jsonb, 0, 'The volume median reads 26.000000 micron and the truncated tail 0.000063372072 at 30, 60, 120 and 600 bins alike. The span is the grid input that moves the tail, and the floor under the bin count is 10.'),
  ('producedwater', 'beginner', 'final', null, 15, 'What is the truncated tail a bin set reports?', '["The volume in the finest bin of the grid, which is where all the droplets too small for any device here to remove are gathered up.", "The volume of the distribution lying outside the span of the grid, which the normalisation absorbs so the bins sum to the whole.", "The volume the module refuses to describe, which is why a grid narrower than 3 sigma either side is declined.", "The difference between the typed median and the volume median of the bin set, which is the way this module reports that identity."]'::jsonb, 1, 'It falls from 0.002699934563 to 0.000000001980 as the span widens from 3 sigma to 6, and it holds across a sweep of the bin count from 30 to 600. Reporting it is what lets a reader judge the grid.'),
  ('producedwater', 'beginner', 'final', null, 16, 'The module defaults to 60 bins spanning 4 sigma either side, and reports both back on every answer. Why report them?', '["The grid is an input the caller usually supplies, so echoing it back confirms what the module received.", "The grid is what the truncated tail is computed from, and the tail cannot be interpreted without it.", "The grid is declared rather than derived, and every declared value in this module is echoed on the return that uses it.", "The grid moves the answer, so it is reported rather than hidden, which is what lets a reader see which grid produced the figure."]'::jsonb, 3, 'Both figures are declared constants with floors under them, at 10 bins and 3 sigma. The span is what moves the tail, and reporting the grid is a statement that it is a modelling choice rather than an implementation detail.'),
  ('producedwater', 'beginner', 'final', null, 17, 'A caller types a droplet spread of 1.5 into the studio. Does an answer come back?', '["No, because a spread of 1.5 is past anything this method will describe, and what comes back carries a named error instead.", "Yes, with a note saying the figure sits outside the customary band, and the removal of 68.402514 percent arrives with it.", "Yes, with no note at all, because the customary band runs to 2 and 1.5 sits comfortably inside it.", "Yes, with a note saying that the outlet median of 5.944722 micron has fallen below the floor any median is reported down to."]'::jsonb, 1, 'Doubt is reported and the figure still arrives. A value this method has nothing to say about is declined by name instead, and that happens above 2.'),
  ('producedwater', 'beginner', 'final', null, 18, 'At a fixed cut size of 12 micron the removal reads 80.243119 percent at sigma 0.7 and 74.748250 at sigma 1. Which input moved, and what does the pair show?', '["Only the median of the droplet population moved, and a lower median of course leaves rather less of the oil above the cut size.", "Only the spread of the droplet population moved, and a wider spread puts oil volume into droplets far below the cut, which pass.", "Only the cut size moved, since a removal quoted at one cut size cannot change unless the device does.", "Only the grid moved, since a wider distribution is described on a grid that reaches further out."]'::jsonb, 1, 'The device is unchanged throughout, so nothing in that column can be blamed on the equipment or on how it was sized. Sigma is the input a reader is least likely to have measured and it moves the answer hardest.'),
  ('producedwater', 'beginner', 'final', null, 19, 'A device at a 12 micron cut removes 78.263077 percent of the oil in this water and leaves a surviving volume of 0.217369227363. What is that second figure for?', '["It is the fraction of the droplets left rather than of the volume, which is the count basis the module reports beside the volume one.", "It is the truncated tail of the outlet grid, which the module reports so a reader can judge how much was thrown away.", "It is the oil left below the dissolved and soluble floor, which no device in this module removes.", "It is what the outlet bins are normalised by, so the distribution handed on still sums to the whole."]'::jsonb, 3, 'The removal and the surviving volume are the two halves of one fraction of the oil. The truncated tail is a property of the span of the grid, and the floor under an outlet has no value stated in this module at all.'),
  ('producedwater', 'beginner', 'final', null, 20, 'What is the argument for a check like the volume median of a bin set reproducing its own d50?', '["It is stronger than a published comparison, since a module that matches an identity will match a measurement as well.", "It replaces a published comparison, since a module with identities in it does not need other people''s data at all.", "It is what the golden file is built from, so every published case in this module rests on it.", "It needs no published dataset, no vendor test and no field sample, and it is unambiguous, which published comparisons frequently are not."]'::jsonb, 3, 'Validation usually means finding a published case and matching it, which is slow and depends on somebody else''s measurement being right. Identities are the other half of the job.'),
  ('producedwater', 'beginner', 'final', null, 21, 'On the UZERE inlet at 60 bins and 4 sigma, the finest bin starts at 1.059817303438 micron. What sets that edge?', '["The bin count, since a grid cut into more bins reaches further down into the fine end of the distribution it describes.", "The span of the grid below the median, since the edges come from how far the grid reaches rather than from how finely it is cut.", "The floor under a reported median, below which this module stops describing the droplet population that is left in the water at all.", "The finest droplet this module will describe at all, which is a declared value and sits in the frozen object with the rest."]'::jsonb, 1, 'The coarsest bin moves from 286.602586 micron to 3159.270855 as the span goes from 3 sigma to 6, and the bin count sweep from 30 to 600 moves neither edge nor the tail.'),
  ('producedwater', 'beginner', 'final', null, 22, 'At 5 micron in the UZERE water the closed form and the full drag balance agree to 8.83e-5. What makes that agreement worth anything?', '["They are the engine and the oracle, so the agreement is between two files maintained by different people.", "They are evaluated at the same Reynolds number on every row, so any disagreement between them would have to come out of the fluid properties.", "They are two different methods, one closed form and one a damped iteration on a drag coefficient, rather than two copies of one calculation.", "They are both stated to creeping flow, so agreement inside the band is what both of them were derived to give."]'::jsonb, 2, 'Identical to twelve decimals is what two copies of one calculation produce. The value is in the two routes being independent, which is why the departure outside the band is informative as well.'),
  ('producedwater', 'beginner', 'final', null, 23, 'A droplet of 240 micron in this water puts the two routes at a ratio of 1.224295. How does the module treat an answer there?', '["It reports the velocity from the full drag balance instead, on the grounds that the closed form has left the regime it was derived in.", "It reports the velocity and marks the rule as incomplete, which is the way this module handles any criterion it applies only half of.", "It reports the velocity and warns, because the departure is smooth and a number just past the line is nearly as good as one just inside it.", "It refuses to answer, because 2.198987 is well past the Reynolds number of 1 that the closed form in this module is stated to and warned about."]'::jsonb, 2, 'Declining would throw away a usable figure to make a point about a boundary. An incomplete rule is the API 421 horizontal velocity check, which is a different matter entirely.'),
  ('producedwater', 'beginner', 'final', null, 24, 'Why does this module warn about a droplet outside the creeping flow band rather than leaving it to the reader?', '["The closed form gives the smaller velocity, so the error is conservative, and a conservative error wastes capital that nobody can account for.", "The closed form gives the larger velocity, so the error is optimistic, and an optimistic error is the one a designer is least likely to catch by looking at the answer.", "The reader cannot see the Reynolds number otherwise, since it is reported for the inlet median droplet alone.", "The departure is a cliff rather than a slope, so a reader working near the limit has no way of judging how far past it they are."]'::jsonb, 1, 'An overstated rise velocity produces an understated cut size, so the equipment is credited with catching finer oil than it will. There is no cliff in that column and the Reynolds number is reported beside every cut size in the module.'),
  ('producedwater', 'beginner', 'final', null, 25, 'Eighteen times the viscosity times a reported rise velocity, over the diameter squared and the density difference, comes to 9.806650 m/s2. What is that figure''s place in this module?', '["It is a declared constant like the rest, exported in the frozen object so a reviewer can find it.", "It is a calibration, chosen so that the rise velocities this module reports sit where such velocities are customarily credited.", "It is the only number in the device physics that is neither declared nor derived, because it is a property of the planet.", "It is held for literature, which is why the module states the arithmetic rather than the value."]'::jsonb, 2, 'A figure recovered from a return value was demonstrably used by the arithmetic that built that answer, and no amount of rewriting the implementation changes the claim.'),
  ('producedwater', 'beginner', 'final', null, 26, 'A colleague describes the UZERE stream itself as sitting inside the band. What is wrong with saying it that way?', '["The band belongs to a droplet in a water, so one stream carries droplets on both sides of it at the same time.", "The band belongs to the vessel rather than to the water, so it is the basin that sits inside it or outside.", "The band belongs to the closed form rather than to any fluid, so nothing physical can be described as being inside it.", "The band belongs to the grid, so it is the coarsest and finest bins of the distribution that sit inside or outside."]'::jsonb, 0, 'In the same water a droplet of 5 micron sits at a Reynolds number of 0.000020 and one of 500 micron at 19.883778. Every device reports the figure for its own cut droplet for exactly that reason.'),
  ('producedwater', 'beginner', 'final', null, 27, 'A designer proposes to make a basin deeper so that it cuts finer. What does this module say?', '["The cut size gets finer in proportion to the depth, which is what the residence time buys.", "The cut size gets coarser, because a deeper basin runs its water through more slowly and re-entrains less of the oil.", "The cut size does not move, because the droplet has further to rise and exactly proportionally longer to do it.", "The cut size does not move and neither does anything else on the return, since the depth is not an input to this device."]'::jsonb, 2, 'The depth cancels out of the cut size and it does enter the velocity check: the same basin at 1.4 m and at 0.9 m cuts at 165.003927 micron on both rows while the horizontal velocity rises from 0.014154851756 to 0.022018658288 m/s.'),
  ('producedwater', 'beginner', 'final', null, 28, 'Which single declared number carries most of the uncertainty in a plate pack cut size, and why?', '["The short-circuit allowance of 1.5, because it multiplies the surface loading before the rise balance is inverted to give a cut size for the pack.", "The sharpness of 3, because it is what sets how much of the removal falls on either side of the cut size that the pack ends up reporting for this water.", "The 0.7 credited as the settling fraction of the projected plate area, because the effective area, the design rise velocity and the cut size all move with it.", "The reference water of 999 kg/m3, because it sits underneath the crude density, and the whole of the driving force behind the pack is built on that one figure."]'::jsonb, 2, 'It is declared with no source in this repository and it sits directly in the middle of the chain. A reader should hold a plate pack answer a little more loosely than a basin answer for that reason, and should know exactly which number is responsible.'),
  ('producedwater', 'beginner', 'final', null, 29, 'The three published plate cases come back at 23.695934, 100.533332 and 85.316542 micron. What else do those rows carry, and what does it prove?', '["An oracle capture fraction on each row, proving that the marched capture at the reported cut size comes out at one half.", "A removal fraction on each row, proving that the cut size and the removal are computed by two separate routes.", "A channel height independence figure of about two parts in a hundred million million, proving the pack cut does not depend on how the pack is sliced.", "A velocity warning flag on each row, proving that the horizontal velocity check is applied to a plate pack as well."]'::jsonb, 2, 'The oracle marches the same pack at two different channel heights and reports the difference, at 2.21e-14, 2.19e-14 and 2.15e-14. The one published row outside the band is a basin row, and the velocity check belongs to the basin.'),
  ('producedwater', 'beginner', 'final', null, 30, 'At four times its cut size a device at the derived sharpness removes 94.117647 percent and one at the declared sharpness removes 98.461538. What is that pair showing?', '["The sharper curve separates better either side of the cut, and both pass through one half at the cut size itself.", "The sharper curve removes more of the oil everywhere, which is why the declared sharpness is the one used on the gravity devices.", "The two curves belong to two different cut sizes, since a sharpness is the thing a cut size is defined against in the first place.", "The sharper curve is the more conservative of the two, since it credits rather less removal below the cut size than the other one does."]'::jsonb, 0, 'At a quarter of the cut the same two curves read 1.538462 percent and 5.882353, so the sharper one removes less below the cut as well as more above it. One half at a ratio of one is the definition and holds for both.'),
  ('producedwater', 'beginner', 'final', null, 31, 'Which devices in this module carry a sharpness of 3, and what is its status?', '["The gravity and centrifugal devices, and it is declared rather than derived, with no source in this repository.", "The two interception devices, and it is derived from a capture rate that goes as the square of the droplet diameter.", "Every device in the module, and it is derived from the reduced-efficiency form that the grade curve is written in.", "The gravity devices alone, and it was calibrated so that a basin here reproduces the removals published for one."]'::jsonb, 0, 'Sharpness 2 is derived for the two interception devices because their capture rate goes as the square of the droplet diameter. Sharpness 3 was chosen, and the difference between the two is worth real percentage points of removal.'),
  ('producedwater', 'beginner', 'final', null, 32, 'A device is applied to this water at a cut size of 0.001 micron. It removes 99.999999999904 percent and leaves a surviving volume of 9.618e-13. What does the module report about the droplets left?', '["An outlet median at the finest bin edge of the grid, which is as far down as the distribution is described.", "No outlet median at all, because what is left is numerical dust and the shape of it means nothing.", "An outlet median of 4.880416 micron, which is the finest the sweep of cut sizes on this water reaches.", "A refusal, because a device that removes essentially all of the oil has left nothing for a median to be measured on."]'::jsonb, 1, 'The return says the outlet was not normalised and warns in the engine''s own words that what is left is numerical dust. 4.880416 micron is the outlet median at a 2 micron cut on the same water, which does answer.'),
  ('producedwater', 'beginner', 'final', null, 33, 'An allowance of 0 is typed into the studio. What comes back, and in what words?', '["An answer with a note, since an allowance of zero sits outside the customary band in the same way that 1 does.", "An answer computed at the 1.5 the module defaults to, with a line on the return saying the supplied value was unusable.", "A refusal saying that an allowance of zero would put the cut droplet outside the creeping flow band.", "A refusal saying the factor must be positive and this is 0, and that an allowance of zero or less leaves the separator undefined."]'::jsonb, 3, 'Zero and below are declined, and so is anything above the 5 this module holds the allowance to. Each of those states what the quantity is before it states what was wrong with what arrived.'),
  ('producedwater', 'beginner', 'final', null, 34, 'The UZERE reading begins by turning a rate into a flow of 0.051523660393 m3/s. Where does that number come from?', '["28000 barrels of water a day at a barrel declared in the module''s frozen object, over the seconds in a day.", "The plan area of the basin times the surface loading of 0.001981679246 m/s, which is the same quantity read backwards.", "The residence time of 706.471546 s divided into the volume of water this particular basin holds at its design depth.", "28000 barrels of water a day at exactly 0.158987294928 m3 to the barrel, over the seconds in a day."]'::jsonb, 3, 'The barrel is an exact definition rather than a declared choice. The surface loading and the residence are computed from that flow rather than the other way about, although the arithmetic can be read either way.'),
  ('producedwater', 'beginner', 'final', null, 35, 'Nine steps of the UZERE reading pass before the droplets and the equipment finally meet. Which step is it, and what does it need that the eight before it did not?', '["The cut size of 165.003927 micron, which needs the plan area of the basin as well as the fluid properties.", "The rise velocity of 0.000073804485 m/s, which needs a droplet size as well as the two fluids.", "The removal of 3.284882 percent, which needs the droplet distribution and the cut size together.", "The surface loading of 0.001981679246 m/s, which needs the flow as well as a dimension of the vessel."]'::jsonb, 2, 'The rise velocity needs a droplet and the loading needs a vessel, and neither of them puts the two together. The removal is the grade efficiency of the device integrated against the oil volume in every bin.'),
  ('producedwater', 'beginner', 'final', null, 36, 'The UZERE train removes 12.670125 percent. Its basin removes 3.284882 percent of the oil reaching it and its plate pack 9.704008 percent of the oil reaching it. How do those two stage figures combine?', '["Compounded as survivals they give 12.670125 percent exactly, because each is already a fraction of the water that reached its own stage.", "Added they give 12.670125 percent, because both stage figures are fractions of the 650 ppm that entered the train.", "They do not combine at all, because each is a fraction of a different water and no arithmetic on the two of them reaches the overall figure.", "Compounded they overstate the train, because the plate pack figure credits the pack with coarse oil the basin had already taken out."]'::jsonb, 0, 'Each stage figure is a fraction of the water that reached its own stage, so the two survivals multiply straight through to the train outlet of 567.644189 ppm. Adding the two percentages counts oil the plate pack never saw.'),
  ('producedwater', 'beginner', 'final', null, 37, 'What does the second device in that train actually see, and why does it matter?', '["The same population the basin saw, scaled down by the oil the basin removed, which is what a concentration carries.", "A population rebuilt at the outlet median of the first stage, which is how the coupling is passed along the train.", "Whatever the caller supplies for it, since each device in this module is sized against the stream as it arrives at the unit.", "Water whose coarse oil has already been taken out, so it faces a finer population and a harder duty than the raw stream would have given it."]'::jsonb, 3, 'The engine carries the outlet bin distribution of each stage into the next as its inlet, normalised by the volume that survived. The distribution is the state passed down the train and the concentration is a scaling on it.'),
  ('producedwater', 'beginner', 'final', null, 38, 'The UZERE droplet median falls from 26.000000 micron to 23.018983 across that train. What makes those two figures comparable?', '["Both are the volume median of the same bin set, and the module says so on its own return.", "Both are quoted at the same bin count and span, which is what the module reports the grid back for.", "Both are the typed median of the population at that point in the train, one at the inlet and one at the outlet.", "Both are measured on the same basis as the concentrations, which is ppm by mass in and ppm by mass out."]'::jsonb, 0, 'Two numbers a reader will subtract have to be measured the same way. The inlet median reproducing the typed d50 is what makes that statement checkable from outside.'),
  ('producedwater', 'beginner', 'final', null, 39, 'Every figure in the UZERE chain is an input to the one below it. What follows for a temperature typed wrong at the second step?', '["A confidently wrong cut size at the eighth, with every figure in between printing normally on the way down.", "A refusal at the first device, since a temperature that does not belong to the stream will fall outside a stated fit.", "A warning on the return, since the module checks its own intermediate figures against the range each one is stated over.", "An error that cancels, since one temperature enters the viscosity and both densities and the balance carries their ratio."]'::jsonb, 0, 'Nothing in the output is wrong in a sense the engine can detect: each step did exactly what it was asked with what it was given. The only defence is being able to read the chain.'),
  ('producedwater', 'beginner', 'final', null, 40, 'The UZERE reading ends with the engine holding eleven results and declining to say whether the train passes. What would it need?', '["A discharge limit out of its own declared constants, which this module holds for produced water and applies whenever a caller asks it to.", "A complete train, since the verdict was withheld because only two of the three stages a train usually carries were actually built.", "A positive specification supplied by the caller, who is the person who knows the licence, the receiving environment and the regulator.", "An outlet droplet median, since a verdict here is given on the droplet population that is left rather than on the concentration."]'::jsonb, 2, 'This module states no specification of its own and a test asserts its declared constants carry no specification-like key. The train here ran completely and reported both its concentration and its outlet median.'),
  ('producedwater', 'beginner', 'final', null, 41, 'The same basin at 0.9 m of water depth has a residence of 454.160279 s where at 1.4 m it has 706.471546 s. What is that the same fact as?', '["The same flow through a smaller cross section moves faster, which is what the horizontal velocity column is reporting.", "The same flow over a smaller plan area loads the basin harder, which is what the cut size column is reporting.", "The shallower basin holds less water at the same flow, which is why its cut size coarsens on that row.", "The shallower basin gives its droplets less distance to rise, which is why it still separates the same oil in less time."]'::jsonb, 0, 'The plan area did not move between those two rows and the cut size is 165.003927 micron on both. Depth changes the cross section the water crosses, and the velocity and the residence are two readings of that.'),
  ('producedwater', 'beginner', 'final', null, 42, 'Which statement about this module is true as it stands?', '["It computes every cut size from equipment geometry and fluid properties, and it carries the dissolved oil floor as a declared constant.", "It computes every cut size from equipment geometry and fluid properties, and it states no discharge specification of its own.", "It reads a removal efficiency for each device family from its own declared object, and integrates it against the droplet bins.", "It computes a cut size for each device and applies each one to the raw inlet water, reporting the stage removals separately."]'::jsonb, 1, 'The floor is held for literature and the module states its absence on every train return. Nothing here is a fixed efficiency, and each stage is applied to the water reaching it rather than to the inlet.');
